There are two improvements needed in CompileWithTopology:

Since the module is cloned, options.allow_in_place_mlir_modification should be set to true to allow the compiler to perform in-place optimizations on the clone. This is consistent with the implementation in CompileAndLoad.
Ownership of the cloned module should be transferred to HloProgram using the OwningOpRef. Passing std::move(module) (which is just a ModuleOp pointer) does not transfer ownership from clone. This can lead to a use-after-free if the compilation is asynchronous and clone goes out of scope before it completes.

static absl::StatusOr<nb_class_ptr<PyExecutable>>
CompileWithTopology(nb_class_ptr<PyClient> client, mlir::ModuleOp module,
                    const xla::ifrt::Topology &topology,
                    xla::CompileOptions options, ifrt::DeviceListRef devices) {
  mlir::OwningOpRef<mlir::ModuleOp> clone(module.clone());
  options.allow_in_place_mlir_modification = true;
  ifrt::ExecutableRef ifrt_executable;
  {
    auto xla_options =
        std::make_unique<ifrt::XlaCompileOptions>(options, std::move(devices));
#if JAX_IFRT_VERSION_NUMBER >= 47
    TF_ASSIGN_OR_RETURN(ifrt_executable,
                        client->ifrt_client()
                            ->GetDefaultCompiler()
                            ->Compile(std::make_unique<xla::ifrt::HloProgram>(
                                          nullptr, std::move(clone)),
                                      topology, std::move(xla_options))
                            .Await());
#else
    TF_ASSIGN_OR_RETURN(
        ifrt_executable,
        client->ifrt_client()->GetDefaultCompiler()->Compile(
            std::make_unique<xla::ifrt::HloProgram>(nullptr, std::move(clone)),
            topology, std::move(xla_options)));
#endif
  }
  return make_nb_class<PyExecutable>(ifrt_executable);
}

